param([Parameter(Mandatory=$true)][ValidatePattern('^[a-z0-9-]+$')][string]$Name,[switch]$IncludeLive)
$ErrorActionPreference='Stop'
$workspace=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..'));$destination=Join-Path $workspace ('backups/'+$Name+'.zip');if(Test-Path -LiteralPath $destination){throw 'Checkpoint already exists'}
$paths=[Collections.Generic.List[string]]::new()
foreach($relative in @(
 'src/native_audio.js','src/game_audio.js','src/network_speech.js','src/network_speech_view.js','src/network_frontend.js','src/main.js','src/network_scene.js','src/client_projectile_presentation.js','src/network_projectile_presentation.js','src/network_visual_presentation.js','src/visual_scene_runtime.js','src/network_area_visual_presentation.js',
 'scripts/probe-network-renderer.cjs','scripts/inspect-native-network-audio.py','scripts/network-audio-fixture.html','scripts/network-audio-fixture.mjs','scripts/smoke-network-audio.cjs','scripts/verify-network-audio.mjs','scripts/checkpoint-network-audio.ps1','scripts/audit-network-audio-checkpoint.py','test/network-audio-native.test.js','evidence/multiplayer-audio.md',
 'backups/animations/native-network-audio-observations.json','backups/animations/native-network-audio-oracle-v2.txt','backups/animations/network-audio-focused-v2.txt','backups/animations/network-audio-regression-v2.txt','backups/animations/network-audio-build-v2.txt','backups/animations/network-audio-build-v3.txt','backups/animations/network-audio-ui-v1.json','backups/animations/network-audio-ui-v1.png','backups/animations/network-audio-ui-v3.txt',
 'backups/animations/rea-network-audio-sound-create.json','backups/animations/rea-network-audio-ambient-play.json','backups/animations/rea-network-packet40-client.json',
 'backups/animations/rea-network-script-sound-sender.json','backups/animations/rea-feedback-client-router-view.json','backups/animations/rea-native-audio-internal-source-ctor.json','backups/animations/rea-native-audio-source-volume.json','backups/animations/rea-native-audio-internal-play-code.json','backups/animations/rea-native-audio-3d-voice.json','backups/animations/rea-native-audio-positional.json','backups/animations/rea-network-audio-listener-owner.json','backups/animations/rea-network-audio-listener-output.json','backups/animations/rea-network-audio-listener-position.json','backups/animations/rea-network-audio-init-body.json'
)){$paths.Add($relative)}
if($IncludeLive){foreach($relative in @('REPLACEMENT_CLIENT_ROADMAP.md','backups/animations/local-network-character-export-v133.json','backups/animations/local-network-audio-v134.json','backups/animations/local-network-audio-v135.json','backups/animations/network-audio-current-v134.json','backups/animations/network-audio-current-v135.json','backups/animations/network-audio-ready-v134.png','backups/animations/network-audio-ready-v135.png','backups/animations/network-audio-acceptance-v1.json')){if(Test-Path -LiteralPath (Join-Path $workspace $relative)){$paths.Add($relative)}}}
$parents=@('multiplayer-attack-feedback-20261019-v1.zip','multiplayer-attack-feedback-live-20261019-v1.zip','multiplayer-procedural-projectile-live-20261019-v2.zip','multiplayer-light-capacity-live-20261019-v4.zip','multiplayer-model-preparation-live-20261019-v4.zip','multiplayer-character-export-20261019-v2.zip')
$chain=@($parents|ForEach-Object {[ordered]@{archive=$_;sha256=(Get-FileHash -LiteralPath (Join-Path $workspace ('backups/'+$_)) -Algorithm SHA256).Hash}})
Add-Type -AssemblyName System.IO.Compression
$manifest=[Collections.Generic.List[object]]::new();$stream=[IO.File]::Open($destination,[IO.FileMode]::CreateNew);$zip=[IO.Compression.ZipArchive]::new($stream,[IO.Compression.ZipArchiveMode]::Create)
try{
 foreach($relative in $paths){$absolute=[IO.Path]::GetFullPath((Join-Path $workspace $relative));if(-not $absolute.StartsWith($workspace+[IO.Path]::DirectorySeparatorChar,[StringComparison]::OrdinalIgnoreCase)){throw 'Checkpoint source escaped workspace'};$snapshot=[IO.File]::ReadAllBytes($absolute);$entry=$zip.CreateEntry($relative,[IO.Compression.CompressionLevel]::Optimal);$entryStream=$entry.Open();try{$entryStream.Write($snapshot,0,$snapshot.Length)}finally{$entryStream.Dispose()};$manifest.Add([ordered]@{path=$relative;bytes=$snapshot.Length;sha256=[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($snapshot))})}
 foreach($metadata in @(@{name='checkpoint-manifest.json';value=@($manifest.ToArray())},@{name='checkpoint-chain.json';value=[ordered]@{kind='incremental';parents=$chain;restore='Extract parents in order, then overlay this checkpoint.'}})){$entry=$zip.CreateEntry($metadata.name);$writer=[IO.StreamWriter]::new($entry.Open());try{$writer.Write(($metadata.value|ConvertTo-Json -Depth 6))}finally{$writer.Dispose()}}
}finally{$zip.Dispose();$stream.Dispose()}
$verify=[IO.Compression.ZipFile]::OpenRead($destination)
try{if($verify.Entries.Count -ne $paths.Count+2){throw 'Checkpoint count mismatch'};foreach($record in $manifest){$entry=$verify.GetEntry($record.path);if(-not $entry -or $entry.Length -ne $record.bytes){throw ('Length mismatch: '+$record.path)};$entryStream=$entry.Open();$sha=[Security.Cryptography.SHA256]::Create();try{$hash=[Convert]::ToHexString($sha.ComputeHash($entryStream))}finally{$entryStream.Dispose();$sha.Dispose()};if($hash -ne $record.sha256){throw ('Hash mismatch: '+$record.path)}}}finally{$verify.Dispose()}
[ordered]@{path=$destination;files=$paths.Count;bytes=(Get-Item -LiteralPath $destination).Length}|ConvertTo-Json -Compress
